@Test
public void AnalyzeShowRoles() {
    AnalyzesOk("SHOW ROLES");
    AnalyzesOk("SHOW ROLE GRANT GROUP myGroup");
    AnalyzesOk("SHOW CURRENT ROLES");
    AnalysisContext authDisabledCtx = createAuthDisabledAnalysisCtx();
    AnalysisError("SHOW ROLES", authDisabledCtx, "Authorization is not enabled.");
    AnalysisError("SHOW ROLE GRANT GROUP myGroup", authDisabledCtx, "Authorization is not enabled.");
    AnalysisError("SHOW CURRENT ROLES", authDisabledCtx, "Authorization is not enabled.");
}

@Test
public void AnalyzeShowGrantPrincipal() {
    for (String type : new String[] { "ROLE myRole", "USER myUser", "GROUP myGroup" }) {
        AnalyzesOk(String.format("SHOW GRANT %s", type));
        AnalyzesOk(String.format("SHOW GRANT %s ON SERVER", type));
        AnalyzesOk(String.format("SHOW GRANT %s ON DATABASE functional", type));
        AnalyzesOk(String.format("SHOW GRANT %s ON TABLE functional.alltypes", type));
        AnalyzesOk(String.format("SHOW GRANT %s ON COLUMN functional.alltypes.year", type));
        AnalyzesOk(String.format("SHOW GRANT %s ON URI 'hdfs:////test-warehouse//foo'", type));
        AnalysisContext authDisabledCtx = createAuthDisabledAnalysisCtx();
        AnalysisError("SHOW GRANT ROLE myRole", authDisabledCtx, "Authorization is not enabled.");
        AnalysisError("SHOW GRANT ROLE myRole ON SERVER", authDisabledCtx, "Authorization is not enabled.");
    }
    // Determining if a user exists on the system is done in the AuthorizationPolicy and
    // these tests run with authorization disabled. The SHOW GRANT USER will be tested
    // in the custom cluster tests test_grant_revoke.
}

@Test
public void AnalyzeCreateDropRole() throws AnalysisException {
    AnalyzesOk("DROP ROLE myRole");
    AnalyzesOk("CREATE ROLE doesNotExist");
    // Role names are case-insensitive
    AnalyzesOk("DROP ROLE MYrole");
    AnalysisContext authDisabledCtx = createAuthDisabledAnalysisCtx();
    AnalysisError("DROP ROLE myRole", authDisabledCtx, "Authorization is not enabled.");
    AnalysisError("CREATE ROLE doesNotExist", authDisabledCtx, "Authorization is not enabled.");
}

@Test
public void AnalyzeGrantRevokeRole() throws AnalysisException {
    AnalyzesOk("GRANT ROLE myrole TO GROUP abc");
    AnalyzesOk("REVOKE ROLE myrole FROM GROUP abc");
    AnalysisContext authDisabledCtx = createAuthDisabledAnalysisCtx();
    AnalysisError("GRANT ROLE myrole TO GROUP abc", authDisabledCtx, "Authorization is not enabled.");
    AnalysisError("REVOKE ROLE myrole FROM GROUP abc", authDisabledCtx, "Authorization is not enabled.");
}

@Test
public void AnalyzeGrantRevokePriv() throws AnalysisException {
    String[] idents = { "myRole", "ROLE myRole", "GROUP myGroup", "USER myUser" };
    boolean[] isGrantVals = { true, false };
    for (String ident : idents) {
        for (boolean isGrant : isGrantVals) {
            Object[] formatArgs = new String[] { "REVOKE", "FROM", ident };
            if (isGrant)
                formatArgs = new String[] { "GRANT", "TO", ident };
            // ALL privileges
            AnalyzesOk(String.format("%s ALL ON TABLE alltypes %s %s", formatArgs), createAnalysisCtx("functional"));
            AnalyzesOk(String.format("%s ALL ON TABLE functional.alltypes %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALL ON TABLE functional_kudu.alltypes %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALL ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALL ON SERVER %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALL ON SERVER server1 %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALL ON URI 'hdfs:////abc//123' %s %s", formatArgs));
            AnalysisError(String.format("%s ALL ON URI 'xxxx:////abc//123' %s %s", formatArgs), "No FileSystem for scheme: xxxx");
            AnalysisError(String.format("%s ALL ON DATABASE does_not_exist %s %s", formatArgs), "Error setting privileges for database 'does_not_exist'. " + "Verify that the database exists and that you have permissions to issue " + "a GRANT/REVOKE statement.");
            AnalysisError(String.format("%s ALL ON TABLE does_not_exist %s %s", formatArgs), "Error setting privileges for table 'does_not_exist'. " + "Verify that the table exists and that you have permissions to issue " + "a GRANT/REVOKE statement.");
            AnalysisError(String.format("%s ALL ON SERVER does_not_exist %s %s", formatArgs), "Specified server name 'does_not_exist' does not match the " + "configured server name 'server1'");
            // INSERT privilege
            AnalyzesOk(String.format("%s INSERT ON TABLE alltypesagg %s %s", formatArgs), createAnalysisCtx("functional"));
            AnalyzesOk(String.format("%s INSERT ON TABLE functional_kudu.alltypessmall %s %s", formatArgs));
            AnalyzesOk(String.format("%s INSERT ON TABLE functional.alltypesagg %s %s", formatArgs));
            AnalyzesOk(String.format("%s INSERT ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s INSERT ON SERVER %s %s", formatArgs));
            AnalysisError(String.format("%s INSERT ON URI 'hdfs:////abc//123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in " + "privilege spec.");
            // SELECT privilege
            AnalyzesOk(String.format("%s SELECT ON TABLE alltypessmall %s %s", formatArgs), createAnalysisCtx("functional"));
            AnalyzesOk(String.format("%s SELECT ON TABLE functional.alltypessmall %s %s", formatArgs));
            AnalyzesOk(String.format("%s SELECT ON TABLE functional_kudu.alltypessmall %s %s", formatArgs));
            AnalyzesOk(String.format("%s SELECT ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s SELECT ON SERVER %s %s", formatArgs));
            AnalysisError(String.format("%s SELECT ON URI 'hdfs:////abc//123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in " + "privilege spec.");
            // SELECT privileges on columns
            AnalyzesOk(String.format("%s SELECT (id, int_col) ON TABLE functional.alltypes " + "%s %s", formatArgs));
            AnalyzesOk(String.format("%s SELECT (id, id) ON TABLE functional.alltypes " + "%s %s", formatArgs));
            // SELECT privilege on both regular and partition columns
            AnalyzesOk(String.format("%s SELECT (id, int_col, year, month) ON TABLE " + "alltypes %s %s", formatArgs), createAnalysisCtx("functional"));
            AnalyzesOk(String.format("%s SELECT (id, bool_col) ON TABLE " + "functional_kudu.alltypessmall %s %s", formatArgs));
            // Column-level privileges on a VIEW
            AnalyzesOk(String.format("%s SELECT (id, bool_col) ON TABLE " + "functional.alltypes_hive_view %s %s", formatArgs));
            // Empty column list
            AnalysisError(String.format("%s SELECT () ON TABLE functional.alltypes " + "%s %s", formatArgs), "Empty column list in column privilege spec.");
            // INSERT/ALL privileges on columns
            AnalysisError(String.format("%s INSERT (id, tinyint_col) ON TABLE " + "functional.alltypes %s %s", formatArgs), "Only 'SELECT' privileges " + "are allowed in a column privilege spec.");
            AnalysisError(String.format("%s ALL (id, tinyint_col) ON TABLE " + "functional.alltypes %s %s", formatArgs), "Only 'SELECT' privileges " + "are allowed in a column privilege spec.");
            // Columns/table that don't exist
            AnalysisError(String.format("%s SELECT (invalid_col) ON TABLE " + "functional.alltypes %s %s", formatArgs), "Error setting column-level " + "privileges for table 'functional.alltypes'. Verify that both table and " + "columns exist and that you have permissions to issue a GRANT/REVOKE " + "statement.");
            AnalysisError(String.format("%s SELECT (id, int_col) ON TABLE " + "functional.does_not_exist %s %s", formatArgs), "Error setting " + "privileges for table 'functional.does_not_exist'. Verify that the table " + "exists and that you have permissions to issue a GRANT/REVOKE statement.");
            // REFRESH privilege
            AnalyzesOk(String.format("%s REFRESH ON TABLE functional.alltypes %s %s", formatArgs));
            AnalyzesOk(String.format("%s REFRESH ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s REFRESH ON SERVER %s %s", formatArgs));
            AnalyzesOk(String.format("%s REFRESH ON SERVER server1 %s %s", formatArgs));
            AnalysisError(String.format("%s REFRESH ON URI 'hdfs:////abc//123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in privilege spec.");
            // CREATE privilege
            AnalyzesOk(String.format("%s CREATE ON SERVER %s %s", formatArgs));
            AnalyzesOk(String.format("%s CREATE ON SERVER server1 %s %s", formatArgs));
            AnalyzesOk(String.format("%s CREATE ON DATABASE functional %s %s", formatArgs));
            AnalysisError(String.format("%s CREATE ON TABLE functional.alltypes %s %s", formatArgs), "Create-level privileges on tables are not supported.");
            AnalysisError(String.format("%s CREATE ON URI 'hdfs:////abc//123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in privilege spec.");
            // ALTER privilege
            AnalyzesOk(String.format("%s ALTER ON SERVER %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALTER ON SERVER server1 %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALTER ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s ALTER ON TABLE functional.alltypes %s %s", formatArgs));
            AnalysisError(String.format("%s ALTER ON URI 'hdfs:////abc/123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in privilege spec.");
            // DROP privilege
            AnalyzesOk(String.format("%s DROP ON SERVER %s %s", formatArgs));
            AnalyzesOk(String.format("%s DROP ON SERVER server1 %s %s", formatArgs));
            AnalyzesOk(String.format("%s DROP ON DATABASE functional %s %s", formatArgs));
            AnalyzesOk(String.format("%s DROP ON TABLE functional.alltypes %s myrole", formatArgs));
            AnalysisError(String.format("%s DROP ON URI 'hdfs:////abc/123' %s %s", formatArgs), "Only 'ALL' privilege may be applied at URI scope in privilege spec.");
        }
        AnalysisContext authDisabledCtx = createAuthDisabledAnalysisCtx();
        AnalysisError("GRANT ALL ON SERVER TO myRole", authDisabledCtx, "Authorization is not enabled.");
        AnalysisError("REVOKE ALL ON SERVER FROM myRole", authDisabledCtx, "Authorization is not enabled.");
        TQueryCtx noUserNameQueryCtx = TestUtils.createQueryContext(Catalog.DEFAULT_DB, "");
        EventSequence timeline = new EventSequence("Authorization Test");
        AnalysisContext noUserNameCtx = new AnalysisContext(noUserNameQueryCtx, new SentryAuthorizationFactory(SentryAuthorizationConfig.createHadoopGroupAuthConfig("server1", null)), timeline);
        AnalysisError("GRANT ALL ON SERVER TO myRole", noUserNameCtx, "Cannot execute authorization statement with an empty username.");
    }
}

@Test
public void TestAlterTableAddDropPartition() throws CatalogException {
    String[] addDrop = { "add if not exists", "drop if exists" };
    for (String kw : addDrop) {
        // Add different partitions for different column types
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(year=2050, month=10)");
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(month=10, year=2050)");
        AnalyzesOk("alter table functional.insert_string_partitioned " + kw + " partition(s2='1234')");
        // Add/drop date partitions
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part='1874-06-04')");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=date '1874-06-04')");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part='1874-6-04')");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=date '1874-6-04')");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part='1874-6-4')");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=date '1874-6-4')");
        // Can't add/drop partitions to/from unpartitioned tables
        AnalysisError("alter table functional.alltypesnopart " + kw + " partition (i=1)", "Table is not partitioned: functional.alltypesnopart");
        AnalysisError("alter table functional_hbase.alltypesagg " + kw + " partition (i=1)", "Table is not partitioned: functional_hbase.alltypesagg");
        // Empty string partition keys
        AnalyzesOk("alter table functional.insert_string_partitioned " + kw + " partition(s2='')");
        // Arbitrary exprs as partition key values. Constant exprs are ok.
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(year=-1, month=cast((10+5*4) as INT))");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=cast('1874-6-4' as date))");
        // Table/Db does not exist
        AnalysisError("alter table db_does_not_exist.alltypes " + kw + " partition (i=1)", "Could not resolve table reference: " + "'db_does_not_exist.alltypes'");
        AnalysisError("alter table functional.table_does_not_exist " + kw + " partition (i=1)", "Could not resolve table reference: " + "'functional.table_does_not_exist'");
        // Cannot ALTER TABLE a view.
        AnalysisError("alter table functional.alltypes_view " + kw + " partition(year=2050, month=10)", "ALTER TABLE not allowed on a view: functional.alltypes_view");
        AnalysisError("alter table functional.alltypes_datasource " + kw + " partition(year=2050, month=10)", "ALTER TABLE not allowed on a table produced by a data source: " + "functional.alltypes_datasource");
        // NULL partition keys
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(year=NULL, month=1)");
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(year=NULL, month=NULL)");
        AnalyzesOk("alter table functional.alltypes " + kw + " partition(year=ascii(null), month=ascii(NULL))");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=NULL)");
        AnalyzesOk("alter table functional.date_tbl " + kw + " partition(date_part=cast(NULL as date))");
    }
    // Data types don't match
    AnalysisError("alter table functional.insert_string_partitioned add " + "partition(s2=1234)", "Value of partition spec (column=s2) has incompatible type: 'SMALLINT'. " + "Expected type: 'STRING'.");
    AnalysisError("alter table functional.insert_string_partitioned drop " + "partition(s2=1234)", "operands of type STRING and SMALLINT are not comparable: s2 = 1234");
    AnalysisError("alter table functional.date_tbl add partition (date_part=123)", "Value of partition spec (column=date_part) has incompatible type: 'TINYINT'. " + "Expected type: 'DATE'.");
    // Loss of precision
    AnalysisError("alter table functional.alltypes add " + "partition(year=100000000000, month=10) ", "Partition key value may result in loss of precision.\nWould need to cast " + "'100000000000' to 'INT' for partition column: year");
    // Invalid date literal
    AnalysisError("alter table functional.date_tbl add partition (date_part='1874-06-')", "Invalid date literal: '1874-06-'");
    AnalysisError("alter table functional.date_tbl add partition (date_part=date '1874-06-')", "Invalid date literal: '1874-06-'");
    // Duplicate partition key name
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, year=2051)", "Duplicate partition key name: year");
    // Duplicate date partition key name. Date literals may have different variations.
    AnalysisError("alter table functional.date_tbl add partition (date_part='0001-01-01')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition (date_part=DATE '0001-01-01')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition (date_part='0001-01-1')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition (date_part=date '0001-01-1')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition (date_part='0001-01-1')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition (date_part=date '0001-1-1')", "Partition spec already exists: (date_part=DATE '0001-01-01').");
    AnalysisError("alter table functional.date_tbl add partition " + "(date_part=cast('0001-1-01' as date))", "Partition spec already exists: (date_part=CAST('0001-1-01' AS DATE)).");
    // Arbitrary exprs as partition key values. Non-constant exprs should fail.
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, month=int_col) ", "Non-constant expressions are not supported as static partition-key " + "values in 'month=int_col'.");
    AnalysisError("alter table functional.alltypes add " + "partition(year=cast(int_col as int), month=12) ", "Non-constant expressions are not supported as static partition-key " + "values in 'year=CAST(int_col AS INT)'.");
    // Not a partition column
    AnalysisError("alter table functional.alltypes drop " + "partition(year=2050, int_col=1)", "Partition exprs cannot contain non-partition column(s): int_col = 1.");
    // Arbitrary exprs as partition key values. Non-partition columns should fail.
    AnalysisError("alter table functional.alltypes drop " + "partition(year=2050, month=int_col) ", "Partition exprs cannot contain non-partition column(s): `month` = int_col.");
    AnalysisError("alter table functional.alltypes drop " + "partition(year=cast(int_col as int), month=12) ", "Partition exprs cannot contain non-partition column(s): " + "`year` = CAST(int_col AS INT).");
    // IF NOT EXISTS properly checks for partition existence
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10)");
    AnalysisError("alter table functional.alltypes add " + "partition(year=2010, month=10)", "Partition spec already exists: (year=2010, month=10).");
    AnalyzesOk("alter table functional.alltypes add if not exists " + "partition(year=2010, month=10)");
    AnalyzesOk("alter table functional.alltypes add if not exists " + "partition(year=2010, month=10) location " + "'/test-warehouse/alltypes/year=2010/month=10'");
    // IF EXISTS properly checks for partition existence
    // with a fully specified partition.
    AnalyzesOk("alter table functional.alltypes drop " + "partition(year=2010, month=10)");
    AnalysisError("alter table functional.alltypes drop " + "partition(year=2050, month=10)", "No matching partition(s) found.");
    AnalyzesOk("alter table functional.alltypes drop if exists " + "partition(year=2050, month=10)");
    // NULL partition keys
    AnalysisError("alter table functional.alltypes drop " + "partition(year=NULL, month=1)", "No matching partition(s) found.");
    AnalysisError("alter table functional.alltypes drop " + "partition(year=NULL, month is NULL)", "No matching partition(s) found.");
    AnalysisError("alter table functional.date_tbl drop partition(date_part=NULL)", "No matching partition(s) found.");
    // Drop partition using predicates
    // IF EXISTS is added here
    AnalyzesOk("alter table functional.alltypes drop " + "partition(year<2011, month!=10)");
    AnalysisError("alter table functional.alltypes drop " + "partition(1=1, month=10)", "Invalid partition expr 1 = 1. " + "A partition spec may not contain constant predicates.");
    AnalyzesOk("alter table functional.alltypes drop " + "partition(year>1050, month=10)");
    AnalyzesOk("alter table functional.alltypes drop " + "partition(year>1050 and month=10)");
    AnalyzesOk("alter table functional.alltypes drop " + "partition(month=10)");
    AnalyzesOk("alter table functional.alltypes drop " + "partition(month+2000=year)");
    AnalyzesOk("alter table functional.alltypes drop " + "partition(year>9050, month=10)");
    AnalyzesOk("alter table functional.alltypes drop if exists " + "partition(year>9050, month=10)");
    AnalyzesOk("alter table functional.date_tbl drop if exists " + "partition(date_part > '1874-6-2')");
    AnalyzesOk("alter table functional.date_tbl drop if exists " + "partition(date_part > date '1874-6-02')");
    // Not a valid column
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, blah=1)", "Partition column 'blah' not found in table: functional.alltypes");
    AnalysisError("alter table functional.alltypes drop " + "partition(year=2050, blah=1)", "Could not resolve column/field reference: 'blah'");
    // Not a partition column
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, int_col=1) ", "Column 'int_col' is not a partition column in table: functional.alltypes");
    // Caching ops
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) cached in 'testPool'");
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) cached in 'testPool' with replication = 10");
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) uncached");
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, month=10) cached in 'badPool'", "The specified cache pool does not exist: badPool");
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'file:///test-warehouse/alltypes/year=2010/month=10' cached in 'testPool'", "Location 'file:/test-warehouse/alltypes/year=2010/month=10' cannot be cached. " + "Please retry without caching: ALTER TABLE functional.alltypes ADD PARTITION " + "... UNCACHED");
    // Valid URIs.
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'/test-warehouse/alltypes/year=2010/month=10'");
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'hdfs://localhost:20500/test-warehouse/alltypes/year=2010/month=10'");
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'s3a://bucket/test-warehouse/alltypes/year=2010/month=10'");
    AnalyzesOk("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'file:///test-warehouse/alltypes/year=2010/month=10'");
    // Invalid URIs.
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, month=10) location " + "'foofs://bar/test-warehouse/alltypes/year=2010/month=10'", "No FileSystem for scheme: foofs");
    AnalysisError("alter table functional.alltypes add " + "partition(year=2050, month=10) location '  '", "URI path cannot be empty.");
}

@Test
public void TestAlterTableAddMultiplePartitions() {
    for (String cl : new String[] { "if not exists", "" }) {
        // Add multiple partitions.
        AnalyzesOk("alter table functional.alltypes add " + cl + " partition(year=2050, month=10)" + " partition(year=2050, month=11)" + " partition(year=2050, month=12)");
        // Add multiple DATE partitions with different formatting.
        AnalyzesOk("alter table functional.date_tbl add " + cl + " partition(date_part='1970-11-1')" + " partition(date_part='1971-2-01')" + " partition(date_part=DATE '1972-1-1')");
        // Duplicate partition specifications.
        AnalysisError("alter table functional.alltypes add " + cl + " partition(year=2050, month=10)" + " partition(year=2050, month=11)" + " partition(Month=10, YEAR=2050)", "Duplicate partition spec: (month=10, year=2050)");
        // Duplicate DATE partition specifications with different formatting.
        AnalysisError("alter table functional.date_tbl add " + cl + " partition(date_part='1970-1-1')" + " partition(date_part='1971-1-03')" + " partition(date_part='1970-01-01')", "Duplicate partition spec: (date_part=DATE '1970-01-01')");
        // Multiple partitions with locations and caching.
        AnalyzesOk("alter table functional.alltypes add " + cl + " partition(year=2050, month=10) location" + " '/test-warehouse/alltypes/y2050m10' cached in 'testPool'" + " partition(year=2050, month=11) location" + " 'hdfs://localhost:20500/test-warehouse/alltypes/y2050m11'" + " cached in 'testPool' with replication = 7" + " partition(year=2050, month=12) location" + " 'file:///test-warehouse/alltypes/y2050m12' uncached");
        // One of the partitions points to an invalid URI.
        AnalysisError("alter table functional.alltypes add " + cl + " partition(year=2050, month=10) location" + " '/test-warehouse/alltypes/y2050m10' cached in 'testPool'" + " partition(year=2050, month=11) location" + " 'hdfs://localhost:20500/test-warehouse/alltypes/y2050m11'" + " cached in 'testPool' with replication = 7" + " partition(year=2050, month=12) location" + " 'fil:///test-warehouse/alltypes/y2050m12' uncached", "No FileSystem for scheme: fil");
        // One of the partitions is cached in a non-existent pool.
        AnalysisError("alter table functional.alltypes add " + cl + " partition(year=2050, month=10) location" + " '/test-warehouse/alltypes/y2050m10' cached in 'testPool'" + " partition(year=2050, month=11) location" + " 'hdfs://localhost:20500/test-warehouse/alltypes/y2050m11'" + " cached in 'nonExistentTestPool' with replication = 7" + " partition(year=2050, month=12) location" + " 'file:///test-warehouse/alltypes/y2050m12' uncached", "The specified cache pool does not exist: nonExistentTestPool");
    }
    // If 'IF NOT EXISTS' is not used, ALTER TABLE ADD PARTITION cannot add a preexisting
    // partition to a table.
    AnalysisError("alter table functional.alltypes add partition(year=2050, month=1)" + "partition(year=2010, month=1) partition(year=2050, month=2)", "Partition spec already exists: (year=2010, month=1)");
}

@Test
public void TestAlterTableAddColumn() {
    AnalyzesOk("alter table functional.alltypes add column new_col int");
    AnalyzesOk("alter table functional.alltypes add column NEW_COL int");
    AnalyzesOk("alter table functional.alltypes add column if not exists int_col int");
    AnalyzesOk("alter table functional.alltypes add column if not exists INT_COL int");
    // Column name must be unique for add.
    AnalysisError("alter table functional.alltypes add column int_col int", "Column already exists: int_col");
    AnalysisError("alter table functional.alltypes add column INT_COL int", "Column already exists: int_col");
    // Add a column with same name as a partition column.
    AnalysisError("alter table functional.alltypes add column year int", "Column name conflicts with existing partition column: year");
    AnalysisError("alter table functional.alltypes add column if not exists year int", "Column name conflicts with existing partition column: year");
    AnalysisError("alter table functional.alltypes add column YEAR int", "Column name conflicts with existing partition column: year");
    AnalysisError("alter table functional.alltypes add column if not exists YEAR int", "Column name conflicts with existing partition column: year");
    // Invalid column name.
    AnalysisError("alter table functional.alltypes add column `???` int", "Invalid column/field name: ???");
    // Table/Db does not exist.
    AnalysisError("alter table db_does_not_exist.alltypes add column i int", "Could not resolve table reference: 'db_does_not_exist.alltypes'");
    AnalysisError("alter table functional.table_does_not_exist add column i int", "Could not resolve table reference: 'functional.table_does_not_exist'");
    // Cannot ALTER TABLE a view.
    AnalysisError("alter table functional.alltypes_view add column c1 string", "ALTER TABLE not allowed on a view: functional.alltypes_view");
