        String long_property_value = "";
        for (int i = 0; i < MetaStoreUtil.MAX_PROPERTY_VALUE_LENGTH; ++i) {
            long_property_value += 'v';
        }
        // At this point long_property_{key_value} are actually not quite long enough to
