        AnalyzesOk("alter table functional.alltypes " + "set serdeproperties ('" + long_property_key + "'='" + long_property_value + "') ");
        AnalyzesOk("alter table functional.alltypes " + "set tblproperties ('" + long_property_key + "'='" + long_property_value + "') ");
