    AnalysisError("select isnull(cast(0.789 as decimal(20, 20)), " + "cast(123 as decimal(19, 0)))", decimalV2Ctx, "Cannot resolve DECIMAL types of the isnull(DECIMAL(20,20), " + "DECIMAL(19,0)) function arguments. You need to wrap the arguments in a CAST.");
    testDecimalExpr("case 1 when 0 then cast(0.789 as decimal(19, 19)) " + "else cast(123 as decimal(19, 0)) end", ScalarType.createDecimalType(38, 19));
    AnalyzesOk("select case 1 when 0 then cast(0.789 as decimal(19, 19)) " + "else cast(123 as decimal(20, 0)) end", decimalV1Ctx);
    AnalysisError("select case 1 when 0 then cast(0.789 as decimal(19, 19)) " + "else cast(123 as decimal(20, 0)) end", decimalV2Ctx, "Incompatible return types 'DECIMAL(19,19)' and 'DECIMAL(20,0)' " + "of exprs 'CAST(0.789 AS DECIMAL(19,19))' and 'CAST(123 AS DECIMAL(20,0))'.");
}

@Test
public void TestAppxCountDistinctOption() throws AnalysisException {
    TQueryOptions queryOptions = new TQueryOptions();
    queryOptions.setAppx_count_distinct(true);
    // Accumulates count(distinct) for all columns of alltypesTbl or decimalTbl.
    List<String> countDistinctFns = new ArrayList<>();
    // Accumulates count(distinct) for all columns of both alltypesTbl and decimalTbl.
    List<String> allCountDistinctFns = new ArrayList<>();
    Table alltypesTbl = catalog_.getOrLoadTable("functional", "alltypes");
    for (Column col : alltypesTbl.getColumns()) {
        String colName = col.getName();
        // Test a single count(distinct) with some other aggs.
        String countDistinctFn = String.format("count(distinct %s)", colName);
        SelectStmt stmt = (SelectStmt) AnalyzesOk(String.format("select %s, sum(distinct smallint_col), " + "avg(float_col), min(%s) " + "from functional.alltypes", countDistinctFn, colName), createAnalysisCtx(queryOptions));
        validateSingleColAppxCountDistinctRewrite(stmt, colName, 4, 1, 1);
        countDistinctFns.add(countDistinctFn);
    }
    // Test a single query with a count(distinct) on all columns of alltypesTbl.
    SelectStmt alltypesStmt = (SelectStmt) AnalyzesOk(String.format("select %s from functional.alltypes", Joiner.on(",").join(countDistinctFns)), createAnalysisCtx(queryOptions));
    assertAllNdvAggExprs(alltypesStmt, alltypesTbl.getColumns().size());
    allCountDistinctFns.addAll(countDistinctFns);
    countDistinctFns.clear();
    Table decimalTbl = catalog_.getOrLoadTable("functional", "decimal_tbl");
    for (Column col : decimalTbl.getColumns()) {
        String colName = col.getName();
        // Test a single count(distinct) with some other aggs.
        SelectStmt stmt = (SelectStmt) AnalyzesOk(String.format("select count(distinct %s), sum(distinct d1), " + "avg(d2), min(%s) " + "from functional.decimal_tbl", colName, colName), createAnalysisCtx(queryOptions));
        countDistinctFns.add(String.format("count(distinct %s)", colName));
        validateSingleColAppxCountDistinctRewrite(stmt, colName, 4, 1, 1);
    }
    // Test a single query with a count(distinct) on all columns of decimalTbl.
    SelectStmt decimalTblStmt = (SelectStmt) AnalyzesOk(String.format("select %s from functional.decimal_tbl", Joiner.on(",").join(countDistinctFns)), createAnalysisCtx(queryOptions));
    assertAllNdvAggExprs(decimalTblStmt, decimalTbl.getColumns().size());
    allCountDistinctFns.addAll(countDistinctFns);
    countDistinctFns.clear();
    Table dateTbl = catalog_.getOrLoadTable("functional", "date_tbl");
    for (Column col : dateTbl.getColumns()) {
        String colName = col.getName();
        // Test a single count(distinct) with some other aggs.
        String countDistinctFn = String.format("count(distinct %s)", colName);
        SelectStmt stmt = (SelectStmt) AnalyzesOk(String.format("select %s, avg(%s), min(%s) from functional.date_tbl", countDistinctFn, colName, colName), createAnalysisCtx(queryOptions));
        validateSingleColAppxCountDistinctRewrite(stmt, colName, 3, 0, 1);
        countDistinctFns.add(countDistinctFn);
    }
    // Test a single query with a count(distinct) on all columns of dateTbl.
    SelectStmt dateStmt = (SelectStmt) AnalyzesOk(String.format("select %s from functional.date_tbl", Joiner.on(",").join(countDistinctFns)), createAnalysisCtx(queryOptions));
    assertAllNdvAggExprs(dateStmt, dateTbl.getColumns().size());
    allCountDistinctFns.addAll(countDistinctFns);
    // Test a single query with a count(distinct) on all columns of alltypes, decimalTbl
    // and dateTbl.
    SelectStmt comboStmt = (SelectStmt) AnalyzesOk(String.format("select %s from functional.alltypes cross join functional.decimal_tbl " + "cross join functional.date_tbl", Joiner.on(",").join(allCountDistinctFns)), createAnalysisCtx(queryOptions));
    assertAllNdvAggExprs(comboStmt, alltypesTbl.getColumns().size() + decimalTbl.getColumns().size() + dateTbl.getColumns().size());
    // The rewrite does not work for multiple count() arguments.
    SelectStmt noRewriteStmt = (SelectStmt) AnalyzesOk("select count(distinct int_col, bigint_col), " + "count(distinct string_col, float_col) from functional.alltypes");
    assertNoNdvAggExprs(noRewriteStmt, 2);
    // The rewrite only applies to the count() function.
    noRewriteStmt = (SelectStmt) AnalyzesOk("select avg(distinct int_col), sum(distinct float_col) from functional.alltypes", createAnalysisCtx(queryOptions));
    assertNoNdvAggExprs(noRewriteStmt, 2);
}

@Test
public // IMPALA-2233: Regression test for loss of precision through implicit casts.
void TestImplicitArgumentCasts() throws AnalysisException {
    FunctionName fnName = new FunctionName(BuiltinsDb.NAME, "greatest");
    Function tinyIntFn = new Function(fnName, new Type[] { ScalarType.DOUBLE }, Type.DOUBLE, true);
    Function decimalFn = new Function(fnName, new Type[] { ScalarType.TINYINT, ScalarType.createDecimalType(30, 10) }, Type.INVALID, false);
    Assert.assertFalse(tinyIntFn.compare(decimalFn, CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(tinyIntFn.compare(decimalFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF));
    // Check that this resolves to the decimal version of the function.
    Db db = catalog_.getDb(BuiltinsDb.NAME);
    Function foundFn = db.getFunction(decimalFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF);
    assertNotNull(foundFn);
    Assert.assertTrue(foundFn.getArgs()[0].isDecimal());
    // The double version of the function is a non-strict supertype if the arguments are
    // (double, decimal).
    Function doubleDecimalFn = new Function(fnName, new Type[] { ScalarType.DOUBLE, ScalarType.createDecimalType(30, 10) }, Type.INVALID, false);
    foundFn = db.getFunction(doubleDecimalFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNull(foundFn);
    foundFn = db.getFunction(doubleDecimalFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF);
    assertNotNull(foundFn);
    Assert.assertEquals(Type.DOUBLE, foundFn.getArgs()[0]);
    // Float and any precision decimal can be matched to FLOAT non-strictly.
    Function floatDecimalFn = new Function(fnName, new Type[] { ScalarType.FLOAT, ScalarType.createDecimalType(10, 7) }, Type.INVALID, false);
    foundFn = db.getFunction(floatDecimalFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNull(foundFn);
    foundFn = db.getFunction(floatDecimalFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF);
    assertNotNull(foundFn);
    Assert.assertEquals(Type.FLOAT, foundFn.getArgs()[0]);
    // Float and bigint should be matched to double.
    Function floatBigIntFn = new Function(fnName, new Type[] { ScalarType.FLOAT, ScalarType.BIGINT }, Type.INVALID, false);
    foundFn = db.getFunction(floatBigIntFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNotNull(foundFn);
    Assert.assertEquals(Type.DOUBLE, foundFn.getArgs()[0]);
    FunctionName lagFnName = new FunctionName(BuiltinsDb.NAME, "lag");
    // String should not be converted to timestamp or date if string overload available.
    Function lagStringFn = new Function(lagFnName, new Type[] { ScalarType.STRING, Type.TINYINT }, Type.INVALID, false);
    foundFn = db.getFunction(lagStringFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNotNull(foundFn);
    Assert.assertEquals(Type.STRING, foundFn.getArgs()[0]);
    // Date should not be converted to timestamp if date overload is available.
    Function lagDateFn = new Function(lagFnName, new Type[] { ScalarType.DATE, Type.TINYINT }, Type.INVALID, false);
    foundFn = db.getFunction(lagDateFn, CompareMode.IS_INDISTINGUISHABLE);
    Assert.assertNull(foundFn);
    foundFn = db.getFunction(lagDateFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNotNull(foundFn);
    Assert.assertEquals(Type.DATE, foundFn.getArgs()[0]);
    // String is matched non-strictly to date, instead of converting both string and date
    // arguments to timestamp.
    FunctionName ifFnName = new FunctionName(BuiltinsDb.NAME, "if");
    Function ifStringDateFn = new Function(ifFnName, new Type[] { ScalarType.BOOLEAN, ScalarType.STRING, ScalarType.DATE }, Type.INVALID, false);
    foundFn = db.getFunction(ifStringDateFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNull(foundFn);
    foundFn = db.getFunction(ifStringDateFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF);
    Assert.assertNotNull(foundFn);
    Assert.assertEquals(Type.DATE, foundFn.getArgs()[1]);
    Assert.assertEquals(Type.DATE, foundFn.getArgs()[2]);
    // Date is matched non-strictly to timestamp
    ifStringDateFn = new Function(ifFnName, new Type[] { ScalarType.BOOLEAN, ScalarType.TIMESTAMP, ScalarType.DATE }, Type.INVALID, false);
    foundFn = db.getFunction(ifStringDateFn, CompareMode.IS_SUPERTYPE_OF);
    Assert.assertNull(foundFn);
    foundFn = db.getFunction(ifStringDateFn, CompareMode.IS_NONSTRICT_SUPERTYPE_OF);
    Assert.assertNotNull(foundFn);
    Assert.assertEquals(Type.TIMESTAMP, foundFn.getArgs()[1]);
    Assert.assertEquals(Type.TIMESTAMP, foundFn.getArgs()[2]);
}

@Test
public void TestFromListAliases() {
    TestUtils.assumeKuduIsSupported();
    AnalysisError("update a.name set a.name = 'Oskar' from functional_kudu.testtbl a", "'a.name' is not a table alias. Using the FROM clause requires the target table" + " to be a table alias.");
    AnalysisError("update a.name set a.name = 'Oskar' from functional_kudu.testtbl", "'a.name' is not a valid table alias or reference.");
    AnalysisError("Update functional_kudu.testtbl.c set name='Oskar'", "Could not resolve table reference: 'functional_kudu.testtbl.c'");
    AnalyzesOk("update a set a.name = 'values' from functional_kudu.testtbl a " + "where a.zip in (select zip from functional.testtbl limit 10)");
    AnalyzesOk("update functional_kudu.dimtbl set name = 'Oskar' FROM dimtbl", createAnalysisCtx("functional_kudu"));
    AnalysisError("update a set b.name = 'Oskar' FROM dimtbl b", createAnalysisCtx("functional_kudu"), "'a' is not a valid table alias or reference.");
    AnalyzesOk("update a set a.name = 'Oskar' FROM dimtbl a", createAnalysisCtx("functional_kudu"));
    // Table name is an implicit alias
    AnalyzesOk("update functional_kudu.dimtbl set name = 'Oskar' FROM functional_kudu.dimtbl");
    // If explicit alias is set, it has to be used
    AnalysisError("update functional_kudu.dimtbl set name = 'Oskar' FROM functional_kudu" + ".dimtbl foo", "'functional_kudu.dimtbl' is not a valid table alias or reference.");
    // Implicit alias is ok
    AnalyzesOk("update dimtbl set name = 'Oskar' FROM functional_kudu.dimtbl");
    // Duplicate aliases are illegal
    AnalysisError("update dimtbl set name = 'Oskar' FROM functional_kudu.dimtbl, functional" + ".alltypes dimtbl", "Duplicate table alias: 'dimtbl'");
    // Location of the kudu table doesnt matter
    AnalyzesOk("update a set a.name = 'Oskar' from functional.testtbl b, dimtbl a where b.id =" + " a.id ", createAnalysisCtx("functional_kudu"));
    AnalyzesOk("update a set name = 'Oskar' from functional_kudu.testtbl a");
    AnalysisError("update functional_kudu.testtbl set name = 'Oskar' from functional_kudu.dimtbl", "'functional_kudu.testtbl' is not a valid table alias or reference.");
    // Order of target reference is not important
    AnalyzesOk("update a set a.name = b.name FROM functional.testtbl b join functional_kudu" + ".testtbl a on a.id = b.id where a.id = 10");
    AnalyzesOk("delete from functional_kudu.testtbl");
    AnalyzesOk("delete functional_kudu.testtbl from functional_kudu.testtbl");
    AnalyzesOk("delete a from functional_kudu.testtbl a");
    AnalyzesOk("delete a from functional_kudu.testtbl a join functional.testtbl b " + "on a.zip = b.zip");
}

@Test
public void TestUpdate() {
    TestUtils.assumeKuduIsSupported();
    AnalyzesOk("update functional_kudu.dimtbl set name = 'Oskar'");
    // Correct default database resolution
    AnalyzesOk("update dimtbl set name = 'Oskar'", createAnalysisCtx("functional_kudu"));
    // Correct table alias resolution
    AnalyzesOk("update functional_kudu.dimtbl set name = '10'");
    // Check type compatibility, zip is int, 4711 is smallint
    AnalyzesOk("update functional_kudu.testtbl set zip = 4711");
    // Non-compatible types
    AnalysisError("update functional_kudu.dimtbl set name = name < '10'", "Target table 'functional_kudu.dimtbl' is incompatible with source expressions.\n" + "Expression 'name < '10'' (type: BOOLEAN) is not compatible with column " + "'name' (type: STRING)");
    AnalysisError("update functional_kudu.dimtbl set name = name < 10", "operands of type STRING and TINYINT are not comparable: name < 10");
    // Expression with joined slot ref overflows type
    AnalysisError("update a set a.zip = b.zip * a.zip from functional_kudu.testtbl a, functional" + ".testtbl b", "Possible loss of precision for target table 'functional_kudu.testtbl'.\n" + "Expression 'b.zip * a.zip' (type: BIGINT) would need to be cast to INT for" + " column 'zip'");
    // Explicit casting the expression
    AnalyzesOk("update a set a.zip = cast(b.zip * a.zip as int) from functional_kudu.testtbl " + "a, functional.testtbl b");
    // Smallint is implicitly castable
    AnalyzesOk("update a set a.zip = cast(4 as smallint) from functional_kudu.testtbl " + "a, functional.testtbl b");
    // Simple SlotRef
    AnalyzesOk("update functional_kudu.dimtbl set name = name");
    AnalyzesOk("update functional_kudu.dimtbl set name = name, zip = 10");
    // Expressions in set value
    AnalyzesOk("update functional_kudu.dimtbl set name = substr('hallo', 3)");
    // Only Kudu tables can be updated
    AnalysisError("update functional.alltypes set intcol = 99", "Impala does not support modifying a non-Kudu table: functional.alltypes");
    // Non existing column in update
    AnalysisError("update functional_kudu.dimtbl set links='10'", "Could not resolve column/field reference: 'links'");
    // RHS of the join cannot be right side of a left semi join
    AnalysisError("update foo set foo.name = 'Oskar' from functional.dimtbl a left semi join " + "functional_kudu.dimtbl foo on a.zip = foo.zip", "Illegal column/field reference 'foo.id' of semi-/anti-joined table 'foo'");
    // No key column update
    AnalysisError("update functional_kudu.dimtbl set id=99 where name = '10'", "Key column 'id' cannot be updated.");
    // Duplicate target columns are not allowed
    AnalysisError("update functional_kudu.dimtbl set name = '10', name = cast(4 * 3 as string) " + "where name = '9'", "Duplicate value assignment to column: 'name'");
}

