    AnalysisError("select * from functional.allcomplextypes.int_array_col " + "tablesample system (10)", "TABLESAMPLE is only supported on HDFS tables: int_array_col");
    AnalysisError("select * from functional.allcomplextypes a, a.int_array_col " + "tablesample system (10)", "TABLESAMPLE is only supported on HDFS tables: int_array_col");
}

