    AnalyzesOk("select * from (select a.smallint_col+b.smallint_col  c1" + "         from functional.alltypesagg a join functional.alltypessmall b " + "         using (id, int_col)) x " + "         where x.c1 > 100");
    AnalyzesOk("select a.* from" + " (select * from (select id+2 from functional_hbase.alltypessmall) b) a");
    AnalysisError("select * from " + "(select * from functional.alltypes a join " + "functional.alltypes b on (a.int_col = b.int_col)) x", "duplicated inline view column alias: 'id' in inline view 'x'");
    // subquery on the rhs of the join
