    AnalyzesOk("select count(a.x) from (select id+2 x " + "from functional_hbase.alltypessmall) a");
    AnalyzesOk("select * from (select id, zip " + "       from (select * from functional.testtbl) x " + "       group by zip, id having count(*) > 0) x");
    AnalysisError("select zip + count(*) from functional.testtbl", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
