    AnalyzesOk("select a.* from " + "(select int_col from functional.alltypes " + " union all " + " select tinyint_col from functional.alltypessmall) a " + "union all " + "select smallint_col from functional.alltypes");
    AnalyzesOk("select a.* from " + "(select int_col from functional.alltypes " + " union all " + " select b.smallint_col from " + "  (select smallint_col from functional.alltypessmall" + "   union all" + "   select tinyint_col from functional.alltypes) b) a");
    // negative union test, column labels are inherited from first select block
    AnalysisError("select tinyint_col from " + "(select int_col from functional.alltypes " + " union all " + " select tinyint_col from functional.alltypessmall) a", "Could not resolve column/field reference: 'tinyint_col'");
    // negative aggregate test
    AnalysisError("select * from " + "(select id, zip from functional.testtbl group by id having count(*) > 0) x", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select * from " + "(select id from functional.testtbl group by id having zip + count(*) > 0) x", "HAVING clause not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select * from " + "(select zip, count(*) from functional.testtbl group by 3) x", "GROUP BY: ordinal exceeds the number of items in the SELECT list");
    AnalysisError("select * from " + "(select * from functional.alltypes group by 1) x", "cannot combine '*' in select list with grouping or aggregation");
