public void TestKuduStatements() throws AuthorizationException, AnalysisException {
    TestUtils.assumeKuduIsSupported();
    // Select
    Set<TAccessEvent> accessEvents = AnalyzeAccessEvents("select * from functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT")));
    // Insert
    accessEvents = AnalyzeAccessEvents("insert into functional_kudu.testtbl (id) select id from " + "functional_kudu.alltypes");
