    // Upsert
    accessEvents = AnalyzeAccessEvents("upsert into functional_kudu.testtbl (id) select id from " + "functional_kudu.alltypes");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Delete
    accessEvents = AnalyzeAccessEvents("delete from functional_kudu.testtbl where id = 1");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Delete using a complex query
    accessEvents = AnalyzeAccessEvents("delete c from functional_kudu.testtbl c, functional_kudu.alltypes s where " + "c.id = s.id and s.int_col < 10");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Update
    accessEvents = AnalyzeAccessEvents("update functional_kudu.testtbl set name = 'test' where id < 10");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Drop table
    accessEvents = AnalyzeAccessEvents("drop table functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "DROP")));
    // Show create table
    accessEvents = AnalyzeAccessEvents("show create table functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "VIEW_METADATA")));
    // Compute stats
    accessEvents = AnalyzeAccessEvents("compute stats functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALTER"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT")));
    // Describe
    accessEvents = AnalyzeAccessEvents("describe functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ANY")));
    // Describe formatted
    accessEvents = AnalyzeAccessEvents("describe formatted functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ANY")));
}

/**
 * Baseline test of metadata cardinality, NDVs and null count.
 * Locks down the values used in later tests to catch external changes
 * easily.
 *
 * Cases:
 * - With stats
 *   - Columns without nulls
 *   - Columns with nulls
 * - Without stats, estimated from file size and schema
 *
 * (The last bit is not yet available.)
 */
@Test
public void testMetadata() throws DatabaseNotFoundException, InternalException {
    Catalog catalog = session_.catalog();
    Db db = catalog.getDb("functional");
    StmtMetadataLoader mdLoader = new StmtMetadataLoader(session_.frontend(), "functional", null);
    Set<TableName> tables = Sets.newHashSet(new TableName("functional", "alltypes"), new TableName("functional", "nullrows"), new TableName("functional", "manynulls"));
    mdLoader.loadTables(tables);
    // Table with stats, no nulls
    Table allTypes = db.getTable("alltypes");
    assertEquals(7300, allTypes.getTTableStats().getNum_rows());
    verifyTableCol(allTypes, "id", 7300, 0);
    verifyTableCol(allTypes, "bool_col", 2, 0);
    verifyTableCol(allTypes, "int_col", 10, 0);
    // Bug: NDV of partition columns is -1 though it is listed as
    // 2 in the shell with: SHOW COLUMN STATS alltypes
    //verifyTableCol(allTypes, "year", 2, 0);
    // Bug: When tests are run in Eclipse we get the result above.
    // But, when the same test is run using maven from the command line,
    // we get the result shown below.
    // Unit test in Eclipse see the above, unit tests run from the
    // Disabling both to avoid a flaky test,
    // Same issue for the next three tests.
    //verifyTableCol(allTypes, "year", -1, -1);
    //verifyTableCol(allTypes, "month", 12, 0);
    //verifyTableCol(allTypes, "month", -1, -1);
    // Table with stats and nulls
    Table nullrows = db.getTable("nullrows");
    assertEquals(26, nullrows.getTTableStats().getNum_rows());
    verifyTableCol(nullrows, "id", 26, 0);
    // Bug: NDV should be 1 to include nulls
    verifyTableCol(nullrows, "null_str", 0, 26);
    verifyTableCol(nullrows, "group_str", 6, 0);
    verifyTableCol(nullrows, "some_nulls", 6, 20);
    // Oddly, boolean columns DO include nulls in NDV.
    verifyTableCol(nullrows, "bool_nulls", 3, 15);
    // Table without stats
    Table manynulls = db.getTable("manynulls");
    // Bug: Table cardinality should be guessed from schema & file size.
    assertEquals(-1, manynulls.getTTableStats().getNum_rows());
    verifyTableCol(manynulls, "id", -1, -1);
