        fail();
    } catch (SqlCastException e) {
        // Expected
    }
    // Round to integer
    result = NumericLiteral.convertValue(new BigDecimal("1234.56"), Type.INT);
    assertEquals("1235", result.toString());
    // Round to decimal precision
    BigDecimal input = new BigDecimal("1234.56789");
    result = NumericLiteral.convertValue(input, ScalarType.createDecimalType(7, 3));
    assertEquals("1234.568", result.toString());
    result = NumericLiteral.convertValue(input, ScalarType.createDecimalType(4, 0));
    assertEquals("1235", result.toString());
