        // Test hints in a multi-way join.
        TestJoinHints(String.format("select * from functional.alltypes a " + "join %sbroadcast%s functional.alltypes b using(id) " + "join %sshuffle%s functional.alltypes c using(int_col) " + "join %sbroadcast%s functional.alltypes d using(int_col) " + "join %sshuffle%s functional.alltypes e using(string_col)", prefix, suffix, prefix, suffix, prefix, suffix, prefix, suffix), "broadcast", "shuffle", "broadcast", "shuffle");
        // Test hints in a multi-way join (flipped prefix/suffix -> bad hint start/ends).
        ParserError(String.format("select * from functional.alltypes a " + "join %sbroadcast%s functional.alltypes b using(id) " + "join %sshuffle%s functional.alltypes c using(int_col) " + "join %sbroadcast%s functional.alltypes d using(int_col) " + "join %sshuffle%s functional.alltypes e using(string_col)", prefix, suffix, suffix, prefix, prefix, suffix, suffix, prefix));
        // Test hints in a multi-way join (missing prefixes/suffixes).
        ParserError(String.format("select * from functional.alltypes a " + "join %sbroadcast%s functional.alltypes b using(id) " + "join %sshuffle%s functional.alltypes c using(int_col) " + "join %sbroadcast%s functional.alltypes d using(int_col) " + "join %sshuffle%s functional.alltypes e using(string_col)", suffix, suffix, suffix, suffix, prefix, "", "", ""));
        // Test insert/CTAS hints.
        TestInsertAndCtasHints("t", "t", hintStyle, "noshuffle", "noshuffle");
        TestInsertAndCtasHints("t partition(x, y)", "t partitioned by(x, y)", hintStyle, "noshuffle", "noshuffle");
        TestInsertAndCtasHints("t(a, b) partition(x, y)", "t partitioned by(x, y)", hintStyle, "shuffle", "shuffle");
        TestInsertAndCtasHints("t(a, b) partition(x, y)", "t partitioned by(x, y)", hintStyle, "foo,bar,baz", "foo", "bar", "baz");
        // Test upsert hints.
        TestInsertStmtHints("upsert %s into t %s select * from t", String.format("%sshuffle%s", prefix, suffix), "shuffle");
        TestInsertStmtHints("upsert %s into t (x, y) %s select * from t", String.format("%sshuffle%s", prefix, suffix), "shuffle");
        // Test TableRef hints.
        TestTableHints(String.format("select * from functional.alltypes %sschedule_disk_local%s", prefix, suffix), "schedule_disk_local");
        TestTableHints(String.format("select * from functional.alltypes %sschedule_cache_local," + "schedule_random_replica%s", prefix, suffix), "schedule_cache_local", "schedule_random_replica");
        TestTableHints(String.format("select * from functional.alltypes a %sschedule_cache_local," + "schedule_random_replica%s", prefix, suffix), "schedule_cache_local", "schedule_random_replica");
        TestTableHints(String.format("select * from functional.alltypes a %sschedule_cache_local," + "schedule_random_replica%s" + ", functional.alltypes b %sschedule_remote%s", prefix, suffix, prefix, suffix), "schedule_cache_local", "schedule_random_replica", "schedule_remote");
        // Test both TableRef and join hints.
        TestTableAndJoinHints(String.format("select * from functional.alltypes a %sschedule_cache_local," + "schedule_random_replica%s join %sbroadcast%s functional.alltypes b " + "%sschedule_remote%s using(id)", prefix, suffix, prefix, suffix, prefix, suffix), "schedule_cache_local", "schedule_random_replica", "broadcast", "schedule_remote");
        TestSelectListHints(String.format("select %sfoo,bar,baz%s * from functional.alltypes a", prefix, suffix), "foo", "bar", "baz");
        // Test select-list hints (e.g., straight_join). The legacy-style hint has no
        // prefix and suffix.
        {
            String localPrefix = prefix;
            String localSuffix = suffix;
            if (prefix == "[") {
                localPrefix = "";
                localSuffix = "";
            }
            TestSelectListHints(String.format("select %sstraight_join%s * from functional.alltypes a", localPrefix, localSuffix), "straight_join");
        }
        // Below are tests for hints that are not supported by the legacy syntax.
        if (prefix == "[")
            continue;
        // Test mixing commented hints and comments.
        for (String[] commentStyle : commentStyles) {
            String commentPrefix = commentStyle[0];
            String commentSuffix = commentStyle[1];
            String queryTemplate = "$1comment$2 select $1comment$2 $3straight_join$4 $1comment$2 * " + "from $1comment$2 functional.alltypes a join $1comment$2 $3shuffle$4 " + "$1comment$2 functional.alltypes b $1comment$2 on $1comment$2 " + "(a.id = b.id)";
            String query = queryTemplate.replaceAll("\\$1", commentPrefix).replaceAll("\\$2", commentSuffix).replaceAll("\\$3", prefix).replaceAll("\\$4", suffix);
            TestSelectListHints(query, "straight_join");
            TestJoinHints(query, "shuffle");
        }
        // Tests for hints with arguments.
        TestInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(a)%s", prefix, suffix), "hint_with_args(a)");
        TestInsertStmtHints("insert %s into t %s select * from t", String.format("%sclustered,shuffle,hint_with_args(a)%s", prefix, suffix), "clustered", "shuffle", "hint_with_args(a)");
        TestInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(a,b)%s", prefix, suffix), "hint_with_args(a,b)");
        TestInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(a  , b)%s", prefix, suffix), "hint_with_args(a,b)");
        TestInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(  a  , b , c  , d, e, f    )%s", prefix, suffix), "hint_with_args(a,b,c,d,e,f)");
        ParserErrorOnInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(  a  ,  , ,,, b  )%s", prefix, suffix));
        TestInsertAndCtasHints("t", "t", hintStyle, "hint_with_args(a)", "hint_with_args(a)");
        TestInsertAndCtasHints("t", "t", hintStyle, "clustered,shuffle,hint_with_args(a)", "clustered", "shuffle", "hint_with_args(a)");
        TestInsertAndCtasHints("t", "t", hintStyle, "hint_with_args(a,b)", "hint_with_args(a,b)");
        TestInsertAndCtasHints("t", "t", hintStyle, "hint_with_args(a  , b)", "hint_with_args(a,b)");
        ParserErrorOnInsertStmtHints("insert %s into t %s select * from t", String.format("%shint_with_args(  a  ,  , ,,, b  )%s", prefix, suffix));
        ParserError(String.format("create table t %shint_with_args(  a  ,  , ,,, b  )%s as select * from t", prefix, suffix));
        // Negative tests for hints cannot be specified at the both available locations.
        ParserError(String.format("insert %s into t %s select * from t", String.format("%sshuffle%s", prefix, suffix), String.format("%sclustered%s", prefix, suffix)));
        ParserError(String.format("upsert %s into t %s select * from t", String.format("%sshuffle%s", prefix, suffix), String.format("%sclustered%s", prefix, suffix)));
    }
    // No "+" at the beginning so the comment is not recognized as a hint.
    TestJoinHints("select * from functional.alltypes a join /* comment */" + "functional.alltypes b using (int_col)", (String) null);
    TestSelectListHints("select /* comment */ * from functional.alltypes", (String) null);
    TestInsertStmtHints("insert %s into t(a, b) partition(x, y) %s select 1", "/* comment */", (String) null);
    TestCtasHints("create /* comment */ table t partitioned by (x, y) as select 1", (String) null);
    TestSelectListHints("select /* -- +straight_join */ * from functional.alltypes", (String) null);
    TestSelectListHints("select /* abcdef +straight_join */ * from functional.alltypes", (String) null);
    TestSelectListHints("select \n-- abcdef +straight_join\n * from functional.alltypes", (String) null);
    TestSelectListHints("select \n-- /*+straight_join\n * from functional.alltypes", (String) null);
    // Commented hints cannot span lines (recognized as comments instead).
    TestSelectListHints("select /*\n +straight_join */ * from functional.alltypes", (String) null);
    TestSelectListHints("select /* +straight_join \n*/ * from functional.alltypes", (String) null);
    TestSelectListHints("select /* +straight_\njoin */ * from functional.alltypes", (String) null);
    ParserError("select -- +straight_join * from functional.alltypes");
    ParserError("select \n-- +straight_join * from functional.alltypes");
    // Missing "/*" or "/*"
    ParserError("select * from functional.alltypes a join + */" + "functional.alltypes b using (int_col)");
    ParserError("select * from functional.alltypes a join /* + " + "functional.alltypes b using (int_col)");
    // Test empty hint tokens.
    TestSelectListHints("select /* +straight_join, ,, */ * from functional.alltypes", "straight_join");
    // Traditional commented hints are not parsed inside a comment.
    ParserError("select /* /* +straight_join */ */ * from functional.alltypes");
}

@Test
public void TestFromClause() {
    String[] tblRefs = new String[] { "tbl", "db.tbl", "db.tbl.col", "db.tbl.col.fld" };
    for (String tbl : tblRefs) {
        ParsesOk(("select * from $TBL src1 " + "left outer join $TBL src2 on " + "  src1.key = src2.key and src1.key < 10 and src2.key > 10 " + "right outer join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "full outer join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "left semi join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "left anti join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "right semi join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "right anti join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 " + "inner join $TBL src3 on " + "  src2.key = src3.key and src3.key < 10 ").replace("$TBL", tbl));
        ParsesOk(("select * from $TBL src1 " + "left outer join $TBL src2 using (a, b, c) " + "right outer join $TBL src3 using (d, e, f) " + "full outer join $TBL src4 using (d, e, f) " + "left semi join $TBL src5 using (d, e, f) " + "left anti join $TBL src6 using (d, e, f) " + "right semi join $TBL src7 using (d, e, f) " + "right anti join $TBL src8 using (d, e, f) " + "join $TBL src9 using (d, e, f) " + "inner join $TBL src10 using (d, e, f) ").replace("$TBL", tbl));
        // Test cross joins
        ParsesOk("select * from $TBL cross join $TBL".replace("$TBL", tbl));
    }
    // Test NULLs in on clause.
    ParsesOk("select * from src src1 " + "left outer join src src2 on NULL " + "right outer join src src3 on (NULL) " + "full outer join src src3 on NULL " + "left semi join src src3 on (NULL) " + "left anti join src src3 on (NULL) " + "right semi join src src3 on (NULL) " + "right anti join src src3 on (NULL) " + "join src src3 on NULL " + "inner join src src3 on (NULL) " + "where src2.bla = src3.bla " + "order by src1.key, src1.value, src2.key, src2.value, src3.key, src3.value");
    // Arbitrary exprs in on clause parse ok.
    ParsesOk("select * from src src1 join src src2 on ('a')");
    ParsesOk("select * from src src1 join src src2 on (f(a, b))");
    ParserError("select * from src src1 " + "left outer join src src2 on (src1.key = src2.key and)");
    // Using clause requires SlotRef.
    ParserError("select * from src src1 join src src2 using (1)");
    ParserError("select * from src src1 join src src2 using (f(id))");
    // Using clause required parenthesis.
    ParserError("select * from src src1 join src src2 using id");
    // Cross joins do not accept on/using
    ParserError("select * from a cross join b on (a.id = b.id)");
    ParserError("select * from a cross join b using (id)");
}

@Test
public void TestTableSampleClause() {
    String[] tblRefs = new String[] { "tbl", "db.tbl", "db.tbl.col", "db.tbl.col.fld" };
    String[] tblAliases = new String[] { "", "t" };
    String[] tblSampleClauses = new String[] { "", "tablesample system(10)", "tablesample system(100) repeatable(20)" };
    String[] tblHints = new String[] { "", "/* +schedule_remote */", "[schedule_random_replica]" };
    for (String tbl : tblRefs) {
        for (String alias : tblAliases) {
            for (String smp : tblSampleClauses) {
                for (String hint : tblHints) {
                    // Single table.
                    ParsesOk(String.format("select * from %s %s %s %s", tbl, alias, smp, hint));
                    // Multi table.
                    ParsesOk(String.format("select a.* from %s %s %s %s join %s %s %s %s using (id)", tbl, alias, smp, hint, tbl, alias, smp, hint));
                    ParsesOk(String.format("select a.* from %s %s %s %s, %s %s %s %s", tbl, alias, smp, hint, tbl, alias, smp, hint));
                    // Inline view.
                    ParsesOk(String.format("select * from (select 1 from %s %s) v %s %s", tbl, alias, smp, hint));
                }
            }
        }
    }
    // Table alias most come before TABLESAMPLE.
    ParserError("select * from t tablesample (10) a");
    // Hints must come after TABLESAMPLE.
    ParserError("select * from t [schedule_remote] tablesample (10)");
    ParserError("select * from t /* +schedule_remote */ tablesample (10)");
    // Missing SYSTEM.
    ParserError("select * from t tablesample (10)");
    // Missing parenthesis.
    ParserError("select * from t tablesample system 10");
    // Percent must be int literal.
    ParserError("select * from t tablesample system (10 + 10");
    // Missing random seed.
    ParserError("select * from t tablesample system (10) repeatable");
    // Random seed must be an int literal.
    ParserError("select * from t tablesample system (10) repeatable (10 + 10)");
    // Negative percent.
    ParserError("select * from t tablesample system (-10)");
    // Negative random seed.
    ParserError("select * from t tablesample system (10) repeatable(-10)");
}

