        ParsesOk("ALTER TABLE Foo SET " + cacheClause);
        ParsesOk("ALTER TABLE Foo PARTITION(j=0) SET " + cacheClause);
        ParserError("ALTER TABLE Foo PARTITION(j=0) " + cacheClause);
    }
}

