@Test
public void TestGrantRevokePrivilege() {
    String[][] grantRevoke = { { "GRANT", "TO" }, { "REVOKE", "FROM" } };
    String[] resources = { "SERVER", "SERVER foo", "DATABASE foo", "TABLE foo", "URI 'foo'" };
    String[] badResources = { "DATABASE", "TABLE", "URI", "URI foo", "TABLE 'foo'", "SERVER 'foo'", "DATABASE 'foo'" };
    String[] privileges = { "SELECT", "INSERT", "ALL", "REFRESH", "CREATE", "ALTER", "DROP" };
    String[] badPrivileges = { "UPDATE", "DELETE", "UPSERT", "FAKE" };
    String[] columnPrivResource = { "SELECT (a, b) ON TABLE foo", "SELECT () on TABLE foo", "INSERT (a, b) ON TABLE foo", "ALL (a, b) ON TABLE foo" };
    String[] badColumnPrivResource = { "SELECT (a,) ON TABLE foo", "SELECT (*) ON TABLE foo", "SELECT (a), b ON TABLE foo", "SELECT ((a)) ON TABLE foo", "SELECT (a, b) ON URI foo", "SELECT ON TABLE (a, b) foo" };
    String[] idents = { "myRole", "GROUP myGroup", "USER user", "ROLE myRole" };
    String[] badIdents = { "GROUP", "ROLE", "GROUP group", "GROUP role", "USER role", "FOOBAR foobar", "" };
    // Good SQL
    createPrivSQL(grantRevoke, resources, privileges, idents).forEach(this::ParsesOk);
    // Good SQL with grant option
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("GRANT")).map(s -> s + " WITH GRANT OPTION").forEach(this::ParsesOk);
    // Good SQL with revoke option
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("REVOKE")).map(s -> s.replace("REVOKE", "REVOKE GRANT OPTION FOR")).forEach(this::ParsesOk);
    // Column SQL
    createColumnPrivSql(grantRevoke, columnPrivResource, idents).forEach(this::ParsesOk);
    // Bad Resources
    createPrivSQL(grantRevoke, badResources, privileges, idents).forEach(this::ParserError);
    // Bad privileges
    createPrivSQL(grantRevoke, resources, badPrivileges, idents).forEach(this::ParserError);
    // Bad idents
    createPrivSQL(grantRevoke, resources, privileges, badIdents).forEach(this::ParserError);
    // Bad SQL with grant option
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("GRANT")).map(s -> s + " WITH GRANT").forEach(this::ParserError);
    // Bad SQL with grant option
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("GRANT")).map(s -> s + " WITH").forEach(this::ParserError);
    // Bad SQL with revoke option (omit for)
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("REVOKE")).map(s -> s.replace("REVOKE", "REVOKE GRANT OPTION")).forEach(this::ParserError);
    // Bad SQL with revoke option (omit option for)
    createPrivSQL(grantRevoke, resources, privileges, idents).stream().filter(s -> s.contains("REVOKE")).map(s -> s.replace("REVOKE", "REVOKE GRANT")).forEach(this::ParserError);
}

