    }
    {
        // Java function, with location and symbol
        List<Type> args = Lists.newArrayList(Type.VARCHAR, Type.BOOLEAN);
        ScalarFunction fn = new ScalarFunction(new FunctionName("mydb", "fn1"), args, Type.INT, false);
        fn.setBinaryType(TFunctionBinaryType.JAVA);
        fn.setLocation(new HdfsUri("hdfs://foo:123/fns/myfunc.jar"));
        fn.setSymbolName("MyClass");
        String sql = ToSqlUtils.getCreateFunctionSql(Lists.newArrayList(fn));
        String expected = "CREATE FUNCTION mydb.fn1\n" + " LOCATION 'hdfs://foo:123/fns/myfunc.jar'\n" + " SYMBOL='MyClass'\n";
        assertEquals(expected, sql);
    }
    {
        // C++ function, with location and symbol
        List<Type> args = new ArrayList<>();
        ScalarFunction fn = new ScalarFunction(new FunctionName("mydb", "fn1"), args, Type.INT, false);
        fn.setBinaryType(TFunctionBinaryType.NATIVE);
        fn.setLocation(new HdfsUri("hdfs://foo:123/fns/myfunc.so"));
        fn.setSymbolName("myClass");
        String sql = ToSqlUtils.getCreateFunctionSql(Lists.newArrayList(fn));
        String expected = "CREATE FUNCTION mydb.fn1()\n" + " RETURNS INT\n" + " LOCATION 'hdfs://foo:123/fns/myfunc.so'\n" + " SYMBOL='myClass'\n";
        assertEquals(expected, sql);
    }
    {
        // C++ function, with location and symbol
        List<Type> args = Lists.newArrayList(Type.VARCHAR, Type.BOOLEAN);
        ScalarFunction fn = new ScalarFunction(new FunctionName("mydb", "fn1"), args, Type.INT, false);
        fn.setBinaryType(TFunctionBinaryType.NATIVE);
        fn.setLocation(new HdfsUri("hdfs://foo:123/fns/myfunc.so"));
        fn.setSymbolName("myClass");
        String sql = ToSqlUtils.getCreateFunctionSql(Lists.newArrayList(fn));
        String expected = "CREATE FUNCTION mydb.fn1(VARCHAR(*), BOOLEAN)\n" + " RETURNS INT\n" + " LOCATION 'hdfs://foo:123/fns/myfunc.so'\n" + " SYMBOL='myClass'\n";
        assertEquals(expected, sql);
    }
}

