@Test
public void testColumnMaskEnabled() throws ImpalaException {
    if (authzProvider_ == AuthorizationProvider.SENTRY)
        return;
    String policyName = "col_mask";
    for (String tableName : new String[] { "alltypes", "alltypes_view" }) {
        String json = String.format("{\n" + "  \"name\": \"%s\",\n" + "  \"policyType\": 1,\n" + "  \"serviceType\": \"%s\",\n" + "  \"service\": \"%s\",\n" + "  \"resources\": {\n" + "    \"database\": {\n" + "      \"values\": [\"functional\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    },\n" + "    \"table\": {\n" + "      \"values\": [\"%s\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    },\n" + "    \"column\": {\n" + "      \"values\": [\"string_col\"],\n" + "      \"isExcludes\": false,\n" + "      \"isRecursive\": false\n" + "    }\n" + "  },\n" + "  \"dataMaskPolicyItems\": [\n" + "    {\n" + "      \"accesses\": [\n" + "        {\n" + "          \"type\": \"select\",\n" + "          \"isAllowed\": true\n" + "        }\n" + "      ],\n" + "      \"users\": [\"%s\"],\n" + "      \"dataMaskInfo\": {\"dataMaskType\": \"MASK\"}\n" + "    }\n" + "  ]\n" + "}", policyName, RANGER_SERVICE_TYPE, RANGER_SERVICE_NAME, tableName, USER.getShortName());
        try {
            createRangerPolicy(policyName, json);
            rangerImpalaPlugin_.refreshPoliciesAndTags();
            // Queries on columns that are not masked should be allowed.
            authorize("select id from functional.alltypes").ok(onServer(TPrivilegeLevel.ALL));
            authorize("select x from functional.alltypes_view_sub").ok(onServer(TPrivilegeLevel.ALL));
            authorize("select string_col from functional_kudu.alltypes").ok(onServer(TPrivilegeLevel.ALL));
            // Normal select.
            authorize(String.format("select string_col from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Column within a function.
            authorize(String.format("select substr(string_col, 0, 1) from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Select with *.
            authorize(String.format("select * from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Sub-query.
            authorize(String.format("select t.string_col from (select * from functional.%s) t", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // CTE.
            authorize(String.format("with t as (select * from functional.%s) " + "select string_col from t", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // CTAS.
            authorize(String.format("create table t as select * from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Create view.
            authorize(String.format("create view v as select * from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Alter view.
            authorize(String.format("alter view functional.alltypes_view_sub as " + "select * from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Union.
            authorize(String.format("select string_col from functional.%s union select 'hello'", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Update.
            authorize(String.format("update functional_kudu.alltypes set int_col = 1 where string_col in " + "(select string_col from functional.%s)", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Delete.
            authorize(String.format("delete functional_kudu.alltypes where string_col in " + "(select string_col from functional.%s)", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
            // Copy testcase.
            authorize(String.format("copy testcase to '/tmp' select * from functional.%s", tableName)).error(columnMaskError(String.format("functional.%s.string_col", tableName)), onServer(TPrivilegeLevel.ALL));
        } finally {
            deleteRangerPolicy(policyName);
        }
    }
}

