            authorize(String.format("select t.string_col from (select * from functional.%s) t", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // CTE.
            authorize(String.format("with t as (select * from functional.%s) " + "select string_col from t", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // CTAS.
            authorize(String.format("create table t as select * from functional.%s", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Create view.
            authorize(String.format("create view v as select * from functional.%s", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Alter view.
            authorize(String.format("alter view functional.alltypes_view_sub as " + "select * from functional.%s", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Union.
            authorize(String.format("select string_col from functional.%s union select 'hello'", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Update.
            authorize(String.format("update functional_kudu.alltypes set int_col = 1 where string_col in " + "(select string_col from functional.%s)", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Delete.
            authorize(String.format("delete functional_kudu.alltypes where string_col in " + "(select string_col from functional.%s)", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
            // Copy testcase.
            authorize(String.format("copy testcase to '/tmp' select * from functional.%s", tableName)).error(rowFilterError(String.format("functional.%s", tableName)), onServer(TPrivilegeLevel.ALL));
        } finally {
            deleteRangerPolicy(policyName);
        }
    }
}

