@Test
public void TestShortUsernameUsed() throws Exception {
    // Different long variations of the same username.
    List<User> users = Lists.newArrayList(// Historical note: Hadoop 2 accepts kerberos names missing a realm, but insists
    // on having a terminating '@' even when the default realm is intended. Hadoop 3
    // now has more normal name conventions, where to specify the default realm,
    // everything after and including the '@' character is omitted.
    new User(USER.getName() + "/abc.host.com"), new User(USER.getName() + "/abc.host.com@REAL.COM"), new User(USER.getName() + "@REAL.COM"));
    for (User user : users) {
        AnalysisContext ctx = createAnalysisCtx(new SentryAuthorizationFactory(AUTHZ_CONFIG), user.getName());
        //    for (User user : users) {
        //      AnalysisContext ctx = createAnalysisCtx(AUTHZ_CONFIG, user.getName());
        // Can select from table that user has privileges on.
        AuthzOk(ctx, "select * from functional.alltypesagg");
        // Unqualified table name.
        AuthzError(ctx, "select * from alltypes", "User '%s' does not have privileges to execute 'SELECT' on: default.alltypes");
    }
    // If the first character is '/', the short username should be the same as
    // the full username.
    assertEquals("/" + USER.getName(), new User("/" + USER.getName()).getShortName());
