@Test
public void TestStatsExtrapolation() {
    addTestDb("extrap_stats", null);
    Table tbl = addTestTable("create table extrap_stats.t (i int)");
    // Replace/restore the static backend config for this test.
    TBackendGflags gflags = BackendConfig.INSTANCE.getBackendCfg();
    boolean origEnableStatsExtrapolation = gflags.isEnable_stats_extrapolation();
    try {
        gflags.setEnable_stats_extrapolation(true);
        // Both stats are set to a meaningful value.
        runTest(tbl, 100L, 1000L, 0, 0);
        runTest(tbl, 100L, 1000L, 100, 10);
        runTest(tbl, 100L, 1000L, 1000000000, 100000000);
        runTest(tbl, 100L, 1000L, Long.MAX_VALUE, 922337203685477632L);
        runTest(tbl, 100L, 1000L, -100, -1);
        // The extrapolated number of rows should double/triple when the
        // actual data volume doubles/triples.
        runTest(tbl, 1000000000L, 123456789L, 123456789 * 2, 2000000000L);
        runTest(tbl, 1000000000L, 123456789L, 123456789 * 3, 3000000000L);
        runTest(tbl, 7777777777L, 33333333L, 33333333L * 2, 15555555554L);
        runTest(tbl, 7777777777L, 33333333L, 33333333L * 3, 23333333331L);
        // Very small row count and very big total file size.
        runTest(tbl, 1L, Long.MAX_VALUE, 1, 1);
        runTest(tbl, 1L, Long.MAX_VALUE, 100, 1);
        runTest(tbl, 1L, Long.MAX_VALUE, 1000000000, 1);
        runTest(tbl, 1L, Long.MAX_VALUE, Long.MAX_VALUE, 1);
        runTest(tbl, 1L, Long.MAX_VALUE, -100, -1);
        // Very large row count and very small total file size.
        runTest(tbl, Long.MAX_VALUE, 1L, 1, Long.MAX_VALUE);
        runTest(tbl, Long.MAX_VALUE, 1L, 100, Long.MAX_VALUE);
        runTest(tbl, Long.MAX_VALUE, 1L, 1000000000, Long.MAX_VALUE);
        runTest(tbl, Long.MAX_VALUE, 1L, Long.MAX_VALUE, Long.MAX_VALUE);
        runTest(tbl, Long.MAX_VALUE, 1L, -100, -1);
        // No stats are set.
        testInvalidStats(tbl, null, null);
        // Only one of the stats fields is set.
        testInvalidStats(tbl, 100L, null);
        testInvalidStats(tbl, null, 1000L);
        // Stats are set to invalid values.
        testInvalidStats(tbl, -100L, -1000L);
        testInvalidStats(tbl, -100L, 1000L);
        testInvalidStats(tbl, 100L, -1000L);
        // Stats are zero.
        runTest(tbl, 0L, 0L, 0, 0);
        testInvalidStats(tbl, 0L, 0L);
        testInvalidStats(tbl, 100L, 0L);
        testInvalidStats(tbl, 0L, 1000L);
        // Invalid file bytes input.
        runTest(tbl, 100L, 1000L, -1, -1);
        runTest(tbl, 100L, 1000L, Long.MIN_VALUE, -1);
    } finally {
        gflags.setEnable_stats_extrapolation(origEnableStatsExtrapolation);
    }
}

@Test
public void TestStatsExtrapolationConfig() {
    addTestDb("extrap_config", null);
    Table propUnsetTbl = addTestTable("create table extrap_config.tbl_prop_unset (i int)");
    Table propFalseTbl = addTestTable("create table extrap_config.tbl_prop_false (i int) " + "tblproperties('impala.enable.stats.extrapolation'='false')");
    Table propTrueTbl = addTestTable("create table extrap_config.tbl_prop_true (i int) " + "tblproperties('impala.enable.stats.extrapolation'='true')");
    // Replace/restore the static backend config for this test.
    TBackendGflags gflags = BackendConfig.INSTANCE.getBackendCfg();
    boolean origEnableStatsExtrapolation = gflags.isEnable_stats_extrapolation();
    try {
        // Test --enable_stats_extrapolation=false
        gflags.setEnable_stats_extrapolation(false);
        // Table property unset --> Extrapolation disabled
        configTestExtrapolationDisabled(propUnsetTbl);
        // Table property false --> Extrapolation disabled
        configTestExtrapolationDisabled(propFalseTbl);
        // Table property true --> Extrapolation enabled
        configTestExtrapolationEnabled(propTrueTbl);
        // Test --enable_stats_extrapolation=true
        gflags.setEnable_stats_extrapolation(true);
        // Table property unset --> Extrapolation enabled
        configTestExtrapolationEnabled(propUnsetTbl);
        // Table property false --> Extrapolation disabled
        configTestExtrapolationDisabled(propFalseTbl);
        // Table property true --> Extrapolation enabled
        configTestExtrapolationEnabled(propTrueTbl);
    } finally {
        gflags.setEnable_stats_extrapolation(origEnableStatsExtrapolation);
    }
}

/**
 * Randomly picks 10 testcase files from TESTCASE_DATA_DIR and loads them into a
 * clean Catalog and makes sure that the query statement from the testcase can be
 * planned correctly without any errors.
 */
@Test
public void testTestCaseImport() throws Exception {
    FileStatus[] testCaseFiles = FileSystemUtil.getFileSystemForPath(TESTCASE_DATA_DIR).listStatus(TESTCASE_DATA_DIR);
    // Randomly pick testcases and try to replay them.
    Random rand = new Random();
    int maxIterations = 10;
    Preconditions.checkState(testCaseFiles.length > maxIterations);
    for (int i = 0; i < maxIterations; ++i) {
        FileStatus fs = testCaseFiles[rand.nextInt(testCaseFiles.length)];
        if (!fs.getPath().getName().contains(TESTCASE_FILE_PREFIX))
            continue;
        try (PlannerTestCaseLoader testCaseLoader = new PlannerTestCaseLoader()) {
            Catalog srcCatalog = testCaseLoader.getSrcCatalog();
            // Make sure the catalog is empty (just the default database).
            List<Db> dbs = srcCatalog.getDbs(PatternMatcher.MATCHER_MATCH_ALL);
            assert dbs.size() == 1 && dbs.get(0).getName().equals("default");
            // TODO: Include the source cluster plan in the testcase file and compare it
            // here with the plan computed from the local metadata.
            LOG.info(testCaseLoader.loadTestCase(fs.getPath().toString()));
            dbs = srcCatalog.getDbs(PatternMatcher.MATCHER_MATCH_ALL);
            // Atleast one new database should be loaded per testcase.
            assert dbs.size() > 1;
        }
    }
}

@Test
public void TestGetTypeInfo() throws ImpalaException {
    // Verify that the correct number of types are returned.
    TMetadataOpRequest getInfoReq = new TMetadataOpRequest();
    getInfoReq.opcode = TMetadataOpcode.GET_TYPE_INFO;
    getInfoReq.get_info_req = new TGetInfoReq();
    TResultSet resp = execMetadataOp(getInfoReq);
    // DatabaseMetaData.getTypeInfo has 18 columns.
    assertEquals(18, resp.schema.columns.size());
    assertEquals(18, resp.rows.get(0).colVals.size());
    // Validate the supported types
    List<String> supportedTypes = new ArrayList<>();
    for (ScalarType stype : Type.getSupportedTypes()) {
        if (stype.isSupported() && !stype.isInternalType()) {
            supportedTypes.add(stype.getPrimitiveType().name());
        }
    }
    supportedTypes.add("ARRAY");
    supportedTypes.add("MAP");
    supportedTypes.add("STRUCT");
    assertEquals(supportedTypes.size(), resp.rows.size());
    for (TResultRow row : resp.rows) {
        boolean foundType = false;
        String typeName = row.colVals.get(0).getString_val();
        if (supportedTypes.contains(typeName)) {
            supportedTypes.remove(typeName);
            foundType = true;
        }
        assertTrue(foundType);
    }
    assertEquals(supportedTypes.size(), 0);
}

