@Test
public void testSaturatingMultiply() {
    // Positive * positive
    assertEquals(10, MathUtil.saturatingMultiply(2, 5));
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingMultiply(2, Long.MAX_VALUE));
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingMultiply(3, Long.MAX_VALUE / 2));
    // Positive * negative
    assertEquals(-10, MathUtil.saturatingMultiply(2, -5));
    assertEquals(Long.MIN_VALUE, MathUtil.saturatingMultiply(2, Long.MIN_VALUE));
    assertEquals(Long.MIN_VALUE, MathUtil.saturatingMultiply(-3, Long.MAX_VALUE / 2));
    // Negative * negative
    assertEquals(10, MathUtil.saturatingMultiply(-2, -5));
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingMultiply(-1, Long.MIN_VALUE));
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingMultiply(Long.MIN_VALUE / 10, -100));
}

@Test
public void testSaturatingAdd() {
    // No overflow
    assertEquals(1234, MathUtil.saturatingAdd(1200, 34));
    assertEquals(-1, MathUtil.saturatingAdd(Long.MAX_VALUE, Long.MIN_VALUE));
    // Underflow
    assertEquals(Long.MIN_VALUE, MathUtil.saturatingAdd(Long.MIN_VALUE, -1));
    assertEquals(Long.MIN_VALUE, MathUtil.saturatingAdd(Long.MIN_VALUE, Long.MIN_VALUE / 2));
    // Overflow
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingAdd(Long.MAX_VALUE - 10, 11));
    assertEquals(Long.MAX_VALUE, MathUtil.saturatingAdd(Long.MAX_VALUE, Long.MAX_VALUE / 2));
}

@Test
public void testPrintBytes() {
    assertEquals("0B", PrintUtils.printBytes(0L));
    assertEquals("55B", PrintUtils.printBytes(55L));
    assertEquals("1023B", PrintUtils.printBytes(1023L));
    assertEquals("1.00KB", PrintUtils.printBytes(1024L));
    assertEquals("54.16KB", PrintUtils.printBytes(55463L));
    assertEquals("54.16KB", PrintUtils.printBytes(55463L));
    // The exact threshold before rounding is used to choose the unit.
    // TODO: this behaviour seems fairly harmless but wrong
    assertEquals("1024.00KB", PrintUtils.printBytes(1024L * 1024L - 1L));
    assertEquals("1.00MB", PrintUtils.printBytes(1024L * 1024L));
    assertEquals("1.00MB", PrintUtils.printBytes(1024L * 1024L + 10L));
    assertEquals("1.00GB", PrintUtils.printBytes(1024L * 1024L * 1024L));
    assertEquals("1.50GB", PrintUtils.printBytes((long) (1024L * 1024L * 1024L * 1.5)));
    assertEquals("4.00TB", PrintUtils.printBytes(1024L * 1024L * 1024L * 1024L * 4L));
    assertEquals("8.42PB", PrintUtils.printBytes((long) (1024L * 1024L * 1024L * 1024L * 1024L * 8.42)));
    // Negative values always get bytes as unit.
    // TODO: fix this behaviour if needed.
    assertEquals("-10B", PrintUtils.printBytes(-10L));
    assertEquals("-123456789B", PrintUtils.printBytes(-123456789L));
}

